head.script:
scwin.onpageload = function() {

};

scwin.btn_setEdit_onclick = function(e) {
    input1.setEditFormat("######-#######");
};

scwin.btn_setEdit2_onclick = function(e) {
    input1.setValue("1234561234567");
};

scwin.btn_setEdit3_onclick = function(e) {
    input2.setValue("01051970281");
};

scwin.oneditkeyup = function(info) {
    console.log("oldValue = " + info.oldValue + "\nnewValue = " + info.newValue);
};

scwin.dataMap1_onmodelchange = function(info) {
        var key = info.key;        
        if (key === "col1") {
            var value = dataMap1.get( "col1" );        
            if (value) {
                output1.setValue(value);
            }
        } else if (key === "col2") {
            var value = dataMap1.get( "col2" );        
            if (value) {
                output2.setValue(value);
            }
        }
    };

	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}
	scwin.setSimulate = function() {
		scwin.simulateWrapper('#input1', 'key-sequence', {
			sequence: '123'
		});
	}
	scwin.checkVal = function() {
		return WebSquare.wUnit.getDomById('grd_excelGrid_noresult').style.display == 'none';
	}
	scwin.getErrorLog = function() {
		var temp = WebSquare.logger.getLog();
		return temp.indexOf("Cannot read properties of undefined") == -1;
	}	
	scwin.unitTest = function() {
		//Init test
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_setEdit').click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input1').click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.getErrorLog()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run and Stop unit Test
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
